package cc.crafto.ui.server;
import cc.crafto.ui.Protocol;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class CityDashboardTest {
    final UUID player=UUID.randomUUID();
    TownyCivic.Context town(int remaining){return new TownyCivic.Context(player,"Player",UUID.randomUUID(),"Речной город",false,"Житель",UUID.randomUUID(),0,0,16,23,remaining);}
    CityBuildReader.Result builds(boolean known){return new CityBuildReader.Result(List.of(),List.of(),Map.of("hall",2,"store",1),Map.of("hall","Ратуша","store","Склад"),known,List.of(new CityBuildReader.SiteInfo("hall","Ратуша · этап 3",100,64,true,Map.of(),Map.of(),Set.of()),new CityBuildReader.SiteInfo("farm","Ферма",0,0,false,Map.of(),Map.of(),Set.of())));}
    CivicData.Snapshot data(boolean known){return new CivicData.Snapshot(List.of(new CivicData.Contract("task","Собрать материалы","DELIVERY",64,32,Map.of(player.toString(),12)),new CivicData.Contract("ready","Готовое задание","MINING",10,10,Map.of())),List.of(),List.of(),List.of(),"",known);}
    CivicView view(String section,boolean known,CityDashboardView.Access access){var v=new CivicView();CityDashboardView.populate(v,town(7),builds(known),data(known),"12500.00",12,"30",section,access);return v;}
    CityDashboardView.Access full(){return new CityDashboardView.Access("","","","");}
    @Test void metricsUseRealValuesAndUnlimitedIsNotZero(){var v=new CivicView();CityDashboardView.populate(v,town(-1),builds(true),data(true),"12500.00",12,"без лимита","active",full());var m=v.city.getAsJsonArray("metrics");assertEquals("12 500,00",m.get(0).getAsJsonObject().get("value").getAsString());assertEquals(12,m.get(1).getAsJsonObject().get("value").getAsInt());assertEquals(23,m.get(2).getAsJsonObject().get("value").getAsInt());assertEquals("Без лимита",m.get(3).getAsJsonObject().get("value").getAsString());}
    @Test void completedBuildingsAppearOnlyUnderBuildingsWithoutDuplicatingUpgrades(){var active=view("active",true,full());assertEquals(4,active.rows.size());assertFalse(active.rows.stream().anyMatch(r->r.title().equals("Склад")));var buildings=view("builds",true,full());assertEquals(List.of("Ратуша · этап 3","Ферма","Склад"),buildings.rows.stream().map(CivicView.Row::title).toList());}
    @Test void tasksShowReadyFirstAndPersonalContribution(){var v=view("contracts",true,full());assertEquals("Готовое задание",v.rows.getFirst().title());assertTrue(v.rows.get(1).detail().contains("ваш вклад: 12"));assertEquals("Условия выполнены",v.presentation.get(v.rows.getFirst()).get("status").getAsString());}
    @Test void missingCountsAndUnloadedBuildAreNotPresentedAsZeroProgress(){var v=view("builds",false,full());assertFalse(v.city.get("buildsKnown").getAsBoolean());assertFalse(v.city.get("sectionNotice").getAsString().isBlank());assertFalse(v.presentation.get(v.rows.get(1)).get("known").getAsBoolean());}
    @Test void disabledShortcutHasReasonAndNoExecutableKeyAndDoesNotLeakBalance(){var v=view("active",true,new CityDashboardView.Access("Нет доступа к постройкам","","Нужно право просмотра казны","Нет летописи"));var actions=new HashMap<String,CivicView.Action>();var p=v.json("t",actions,0,3);var links=p.getAsJsonObject("city").getAsJsonArray("shortcuts");assertEquals("",links.get(0).getAsJsonObject().get("action").getAsString());assertFalse(actions.containsKey("c0"));assertFalse(actions.containsKey("c4"));assertFalse(actions.containsKey("cm0"));assertFalse(p.getAsJsonObject("city").getAsJsonArray("metrics").toString().contains("12500"));assertEquals("route",actions.get("cm3").kind());assertEquals("map",actions.get("cm3").id());}
    @Test void paginationKeepsAllShortcutsAndOnlyDisplayedRowActions(){var v=view("active",true,full());var actions=new HashMap<String,CivicView.Action>();var p=v.json("t",actions,1,2);assertEquals(2,p.get("pages").getAsInt());assertEquals(6,p.getAsJsonObject("city").getAsJsonArray("shortcuts").size());assertEquals(11,actions.size());assertFalse(actions.containsKey("a0"));assertTrue(actions.containsKey("a2"));assertDoesNotThrow(()->Protocol.decode(Protocol.encode(Protocol.Kind.CIVIC,p)));}
    @Test void insertingConfirmationCannotMislabelItAsProgress(){var v=view("active",true,full());v.rows.addFirst(new CivicView.Row("Подтверждение","Проверьте последствия",new CivicView.Action("review", "server")));var p=v.json("t",new HashMap<>(),0,3);assertFalse(p.getAsJsonArray("rows").get(0).getAsJsonObject().has("presentation"));assertTrue(p.getAsJsonArray("rows").get(1).getAsJsonObject().has("presentation"));}
    @Test void largestPageStaysWithinRealProtocolBudget(){var v=view("contracts",true,full());v.rows.clear();for(int i=0;i<12;i++){var row=new CivicView.Row("Я".repeat(1000),"Ж".repeat(1000),"",new CivicView.Action("contract","x"+i),"Ы".repeat(1000));v.rows.add(row);v.presentation.put(row,Protocol.object("icon","contract","category","Задание города","status","Условия выполнены","done",99999,"total",100000,"known",true));}CityDashboardView.finances(v,new CityFinance(true,"","2026-10-26",1792972800000L,1793059200000L,Long.MAX_VALUE,Long.MAX_VALUE,0,1,true,Map.of("upkeep",Long.MAX_VALUE)),"");var payload=v.json("t",new HashMap<>(),0,12);assertEquals(12,payload.getAsJsonArray("rows").size());assertDoesNotThrow(()->Protocol.encode(Protocol.Kind.CIVIC,payload));}
    @Test void groupingPreservesPrecisionAndDoesNotFabricateBalance(){assertEquals("2 146 788 553,00",CityDashboardView.formatBalance("2146788553.00"));assertEquals("Экономика недоступна",CityDashboardView.formatBalance("Экономика недоступна"));assertTrue(CityDashboardView.shortBalance("121000000000.00").length()<"121 000 000 000,00".length());}
    @Test void cityShortcutsDoNotExposePersonalOrders(){assertFalse(view("active",true,full()).shortcuts.stream().anyMatch(r->r.action().id().equals("orders")));}
    @Test void legacyViewHasNoDashboardEnvelope(){var v=new CivicView();v.rows.add(CivicView.Row.info("Жители","12"));assertFalse(v.json("t",new HashMap<>(),0,6).has("city"));}
}
